/* Explicit extension: this is the one runtime import in the modules the unit
   tests reach, and Node's type stripping resolves relative specifiers as ESM,
   which requires it. Webpack resolves it identically. */
import { makeId } from "./applicationRules.ts";
import type { GFormField } from "../gh-leads/GForm";
import type { ApplicationQuestion } from "./types";

/**
 * The application a site starts with.
 *
 * These are the same questions the public /apply page asks today (see
 * primitives/application/application-x), lifted so the Builder opens on the
 * form that is actually live rather than a blank screen. Once an editor saves,
 * the stored document is the source of truth and this is only ever the seed.
 */
export function defaultQuestions(now: number): ApplicationQuestion[] {
  /* Takes GFormField rather than Omit<ApplicationQuestion, "id">: GFormField
     carries an index signature, and Omit over one collapses the whole type to
     [x: string]: unknown, losing the required `name`. The id is added here so
     callers only write content. */
  const q = (field: GFormField): ApplicationQuestion => ({
    ...field,
    id: makeId("q", now),
  });

  return [
    q({
      name: "fullName",
      type: "text",
      label: "Full Name",
      placeholder: "Your full name",
      required: true,
    }),
    q({
      name: "email",
      type: "email",
      label: "Email Address",
      placeholder: "you@example.com",
      required: true,
    }),
    q({
      name: "phone",
      type: "tel",
      label: "Phone Number",
      placeholder: "(208) 000-0000",
      required: true,
    }),
    q({
      name: "goal",
      type: "select",
      label: "I'm Looking To",
      placeholder: "Choose one",
      required: true,
      options: [
        { label: "Buy a home", value: "buy" },
        { label: "Sell my home", value: "sell" },
        { label: "Buy and sell", value: "both" },
        { label: "Invest", value: "invest" },
      ],
    }),
    q({
      name: "budget",
      type: "select",
      label: "Budget or Expected Price",
      placeholder: "Select a range",
      options: [
        { label: "Under $400,000", value: "under-400k" },
        { label: "$400,000 – $600,000", value: "400-600k" },
        { label: "$600,000 – $900,000", value: "600-900k" },
        { label: "$900,000 – $1.5M", value: "900k-1.5m" },
        { label: "$1.5M and up", value: "1.5m-plus" },
      ],
    }),
    q({
      name: "timeline",
      type: "select",
      label: "Ideal Timeline",
      placeholder: "Select a timeline",
      options: [
        { label: "As soon as possible", value: "asap" },
        { label: "Within 3 months", value: "3-months" },
        { label: "3 – 6 months", value: "3-6-months" },
        { label: "Just exploring", value: "exploring" },
      ],
    }),
    q({
      name: "message",
      type: "textarea",
      label: "Anything Else Sajra Should Know?",
      placeholder: "Tell Sajra anything that would help her help you.",
      rows: 5,
    }),
  ];
}
