// Which repository paths the Application Builder is allowed to write.
//
// This is the whole reason the save endpoint is not a generic file writer. The
// browser sends a path, and an authenticated CMS user is not the same thing as
// a user who may write anywhere in the repository: a bug or a tampered request
// must not be able to overwrite site source, a workflow file, or the image
// manifest.
//
// The rule is deliberately narrow — one directory, one filename shape, one
// extension. Anything else is refused. The Worker applies the same check
// server-side; this copy exists so the client fails early and with the same
// message, NOT so the server can trust the client.

/** The one directory the Application Builder owns. */
export const APPLICATIONS_DIR = "applications";

/** The document holding every application definition. */
export const APPLICATIONS_DOC = `${APPLICATIONS_DIR}/applications.json`;

/**
 * A single path segment: lowercase letters, digits and hyphens, starting with
 * an alphanumeric. No dots, so no extension games and no traversal.
 */
const FILENAME = /^[a-z0-9][a-z0-9-]{0,63}\.json$/;

export type PathCheck = { ok: true } | { ok: false; reason: string };

export function checkApplicationsPath(path: unknown): PathCheck {
  if (typeof path !== "string" || path.length === 0) {
    return { ok: false, reason: "Path must be a non-empty string." };
  }

  if (path.length > 128) {
    return { ok: false, reason: "Path is too long." };
  }

  // Checked explicitly rather than left to the regex, so the refusal says
  // which rule was broken and the intent survives future edits.
  if (path.includes("..")) {
    return { ok: false, reason: "Path must not contain '..'." };
  }

  if (path.startsWith("/") || /^[a-zA-Z]:/.test(path) || path.includes("://")) {
    return { ok: false, reason: "Path must be repository-relative." };
  }

  if (path.includes("\\")) {
    return { ok: false, reason: "Path must use forward slashes." };
  }

  if (path.includes("\0")) {
    return { ok: false, reason: "Path must not contain control characters." };
  }

  const segments = path.split("/");

  if (segments.length !== 2) {
    return {
      ok: false,
      reason: `Path must be exactly '${APPLICATIONS_DIR}/<name>.json'.`,
    };
  }

  if (segments[0] !== APPLICATIONS_DIR) {
    return {
      ok: false,
      reason: `Path must start with '${APPLICATIONS_DIR}/'.`,
    };
  }

  if (!FILENAME.test(segments[1])) {
    return {
      ok: false,
      reason:
        "Filename must be lowercase letters, digits and hyphens, ending in .json.",
    };
  }

  return { ok: true };
}

export function isAllowedApplicationsPath(path: unknown): boolean {
  return checkApplicationsPath(path).ok;
}
